import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u11")

L(1, "O presente regular", "Raiz + t: ik werk, jij werkt, wij werken.",
  ["Formar o presente dos verbos regulares"],
  vocab=[V("v-werken","werken","trabalhar","verb"), V("v-maken","maken","fazer","verb",note="Fazer no sentido de fabricar/criar."),
         V("v-drinken","drinken","beber","verb"), V("v-leren","leren","aprender|ensinar","verb",note="Ik leer Nederlands = estou a aprender neerlandês.")],
  ex=[("Ik werk in Amsterdam.","Trabalho em Amesterdão."),("Jij drinkt koffie.","Tu bebes café."),("Wij leren Nederlands.","Estamos a aprender neerlandês.")],
  gram=[G("g-presente-regular","Presente regular","Raiz = infinitivo sem **-en**: werk(en). **ik** + raiz: ik werk. **jij, u, hij, zij, het** + raiz + **t**: jij werkt, hij werkt. **wij, jullie, zij** = infinitivo: wij werken. Na pergunta, **jij/je** depois do verbo tira o -t: *werk jij?*",
    [("Hij maakt eten.","Ele faz o jantar."),("Werken jullie hier?","Vocês trabalham aqui?")],
    "O presente neerlandês serve também para o «estar a + infinitivo» português: ik werk = trabalho / estou a trabalhar.")],
  review=["v-wonen","v-koffie","v-nederlands"],
  exs=[
    CJ("werken","ik","Ik ___ in Utrecht.", ["werk"], "ik + raiz: werk.", ["v-werken"]),
    CJ("werken","hij","Hij ___ in een ziekenhuis.", ["werkt"], "hij + raiz + t.", ["v-werken"]),
    CJ("drinken","wij","Wij ___ water.", ["drinken"], "Plural = infinitivo.", ["v-drinken"]),
    CJ("maken","jij","Wat ___ jij?", ["maak"], "Pergunta com jij: sem -t. (maken → maak, com «aa» longo.)", ["v-maken"]),
    MA([("werken","trabalhar"),("maken","fazer"),("drinken","beber"),("leren","aprender")], "Verbos regulares.", ["v-werken","v-maken","v-drinken","v-leren"]),
    TR("pt-nl","Estou a aprender neerlandês.", ["Ik leer Nederlands"], "O presente simples serve para ações em curso.", ["v-leren"], bank=["Ik","leer","Nederlands","ben","leren"]),
    TR("nl-pt","Zij drinkt geen koffie, ze drinkt thee.", ["Ela não bebe café, bebe chá"], "«geen» nega substantivos (unidade 14).", ["v-drinken"]),
    FE(["Jij","werk","in","Leiden."], 1, "werkt", "jij + raiz + t: werkt (o -t só cai quando jij vem depois do verbo).", ["v-werken"]),
    LI("Werken jullie hier?", ["Werken jullie hier"], "Vocês trabalham aqui?", "jullie + infinitivo.", ["v-werken"]),
    WO("Ele faz café.", ["Hij","maakt","koffie"], "maken → hij maakt.", ["v-maken"]),
  ], diff=2, mins=5)

L(2, "Vogais longas e consoantes duplas", "lopen → ik loop; zitten → ik zit.",
  ["Aplicar as regras de ortografia à raiz do verbo"],
  vocab=[V("v-kopen","kopen","comprar","verb",note="ik koop"), V("v-zitten","zitten","estar sentado|estar","verb",note="ik zit"),
         V("v-slapen","slapen","dormir","verb",note="ik slaap"), V("v-wachten","wachten","esperar","verb",note="ik wacht, hij wacht (não se dobra o t)")],
  ex=[("Ik koop brood.","Compro pão."),("Zij zit op de stoel.","Ela está sentada na cadeira."),("De baby slaapt.","O bebé dorme."),("Hij wacht op de bus.","Ele espera pelo autocarro.")],
  gram=[G("g-raiz-ortografia","A raiz e a ortografia","A raiz segue as regras de leitura da unidade 4: **lopen → loop**, **kopen → koop**, **slapen → slaap** (vogal longa fica dobrada numa sílaba fechada). **zitten → zit**, **liggen → lig** (consoante dupla fica simples). Se a raiz já acaba em **t**, não se acrescenta outro: hij **zit**, hij **wacht**.",
    [("Ik loop naar huis.","Vou a pé para casa."),("Hij zit thuis.","Ele está em casa.")])],
  review=["v-lopen","v-brood","v-bus"],
  exs=[
    CJ("kopen","ik","Ik ___ een fiets.", ["koop"], "ko-pen → koop (vogal longa dobrada).", ["v-kopen"]),
    CJ("zitten","hij","Hij ___ op de stoel.", ["zit"], "zit-ten → zit; já acaba em t: hij zit.", ["v-zitten"]),
    CJ("slapen","de baby","De baby ___ .", ["slaapt"], "sla-pen → slaap + t.", ["v-slapen"]),
    CJ("wachten","zij (ela)","Zij ___ op de trein.", ["wacht"], "A raiz já acaba em t: zij wacht.", ["v-wachten"]),
    MC("Qual é a forma certa?", ["*ik koop","ik kop|A vogal longa precisa de «oo» numa sílaba fechada.","ik koopt|Com «ik» não se acrescenta -t."], "kopen → ik koop.", ["v-kopen"]),
    MA([("kopen","comprar"),("zitten","estar sentado"),("slapen","dormir"),("wachten","esperar")], "Verbos desta lição.", ["v-kopen","v-zitten","v-slapen","v-wachten"]),
    FE(["Hij","zitt","op","de","bank."], 1, "zit", "Consoante dupla fica simples no fim: zit.", ["v-zitten"]),
    TR("pt-nl","Ele espera pelo autocarro.", ["Hij wacht op de bus"], "wachten op = esperar por.", ["v-wachten","v-bus"]),
    TR("nl-pt","Ik slaap acht uur.", ["Durmo oito horas"], "uur = hora(s).", ["v-slapen","v-acht"]),
    LI("Wij kopen brood.", ["Wij kopen brood"], "Compramos pão.", "Plural: kopen.", ["v-kopen","v-brood"]),
  ], diff=2, mins=5)

L(3, "v vira f, z vira s", "leven → ik leef; lezen → ik lees.",
  ["Aplicar a troca v/f e z/s na raiz"],
  vocab=[V("v-leven","leven","viver","verb",note="ik leef — viver (existir); para morada usa-se wonen."), V("v-lezen","lezen","ler","verb",note="ik lees"),
         V("v-reizen","reizen","viajar","verb",note="ik reis"), V("v-geven","geven","dar","verb",note="ik geef")],
  ex=[("Ik lees een boek.","Leio um livro."),("Zij reist veel.","Ela viaja muito."),("Hij geeft een cadeau.","Ele dá um presente.")],
  gram=[G("g-v-f-z-s","Raiz sem v nem z no fim","Uma palavra neerlandesa não acaba em **v** nem em **z**: na raiz, **v → f** e **z → s**. lezen → ik **lees**, hij **leest**; geven → ik **geef**; reizen → ik **reis**; schrijven → ik **schrijf**. No plural volta o v/z: wij lezen, wij geven.",
    [("Jij leest de krant.","Tu lês o jornal."),("Wij reizen naar Spanje.","Viajamos para Espanha.")])],
  review=["v-schrijven","v-boek","v-krant"],
  exs=[
    CJ("lezen","ik","Ik ___ een boek.", ["lees"], "le-zen → lees (z → s).", ["v-lezen"]),
    CJ("geven","hij","Hij ___ een cadeau.", ["geeft"], "geven → geef + t.", ["v-geven"]),
    CJ("reizen","zij (ela)","Zij ___ veel.", ["reist"], "reizen → reis + t.", ["v-reizen"]),
    CJ("schrijven","jij","Jij ___ een e-mail.", ["schrijft"], "schrijven → schrijf + t.", ["v-schrijven"]),
    MC("Qual é a forma certa?", ["*ik lees","ik leez|Nenhuma palavra acaba em z.","ik les|Vogal longa: «ee»."], "lezen → ik lees.", ["v-lezen"]),
    MA([("leven","viver"),("lezen","ler"),("reizen","viajar"),("geven","dar")], "Verbos com v/z.", ["v-leven","v-lezen","v-reizen","v-geven"]),
    FE(["Ik","geev","je","een","boek."], 1, "geef", "v → f no fim: geef.", ["v-geven"]),
    TR("pt-nl","Ela lê o jornal.", ["[Zij|Ze] leest de krant"], "lezen → leest.", ["v-lezen","v-krant"]),
    TR("nl-pt","Wij reizen naar Spanje.", ["(Nós )viajamos para Espanha","Vamos viajar para Espanha"], "Plural: reizen (o z volta).", ["v-reizen","v-spanje"]),
    LI("Lees jij de krant?", ["Lees jij de krant"], "Lês o jornal?", "Pergunta com jij: lees (sem t).", ["v-lezen"]),
  ], diff=2, mins=5)

L(4, "Verbos irregulares frequentes", "doen, zien, staan, komen — e revisão de gaan e hebben.",
  ["Conjugar os verbos irregulares mais usados"],
  vocab=[V("v-doen","doen","fazer","verb",note="ik doe, jij doet, wij doen — fazer (ações)."), V("v-zien","zien","ver","verb",note="ik zie, jij ziet"),
         V("v-staan","staan","estar de pé|estar","verb",note="ik sta, jij staat"), V("v-komen","komen","vir","verb",note="ik kom, jij komt")],
  ex=[("Wat doe je?","O que fazes? / O que estás a fazer?"),("Ik zie de zee.","Vejo o mar."),("Hij komt morgen.","Ele vem amanhã.")],
  gram=[G("g-irregulares-presente","Verbos curtos","Verbos de uma sílaba como **doen, gaan, staan, zien** têm raízes curtas: ik **doe**, ik **ga**, ik **sta**, ik **zie**; com jij/hij: doet, gaat, staat, ziet. **maken** e **doen** traduzem-se ambos por «fazer»: maken = criar/fabricar (koffie maken), doen = realizar uma ação (wat doe je?).",
    [("Wat doe jij vandaag?","O que fazes hoje?"),("Ik maak een taart.","Faço um bolo.")],
    "Em português «fazer» serve para tudo; em neerlandês escolhe-se entre doen e maken.")],
  review=["v-gaan","v-hebben","v-maken","v-zee","v-morgen"],
  exs=[
    CJ("doen","jij","Wat ___ je?", ["doe"], "Pergunta com je: doe.", ["v-doen"]),
    CJ("zien","hij","Hij ___ de zee.", ["ziet"], "zien → hij ziet.", ["v-zien"]),
    CJ("staan","ik","Ik ___ bij de deur.", ["sta"], "staan → ik sta.", ["v-staan"]),
    CJ("komen","zij (ela)","Zij ___ morgen.", ["komt"], "komen → zij komt.", ["v-komen"]),
    MC("Fazer café diz-se…", ["*koffie maken","koffie doen|Para preparar/criar algo usa-se «maken»."], "maken = fazer (criar).", ["v-maken","v-doen"]),
    MC("«O que estás a fazer?» diz-se…", ["*Wat doe je?","Wat maak je?|Pergunta sobre a atividade: doen."], "doen = fazer (ação).", ["v-doen"]),
    MA([("doen","fazer"),("zien","ver"),("staan","estar de pé"),("komen","vir")], "Irregulares.", ["v-doen","v-zien","v-staan","v-komen"]),
    TR("pt-nl","Ele vem amanhã.", ["Hij komt morgen"], "komen → hij komt.", ["v-komen","v-morgen"], bank=["Hij","komt","morgen","kom","gaat"]),
    FE(["Wat","doet","jij?"], 1, "doe", "Com jij depois do verbo: doe.", ["v-doen"]),
    LI("Ik zie je morgen!", ["Ik zie je morgen"], "Vejo-te amanhã!", "Despedida comum.", ["v-zien","v-morgen"]),
  ], diff=2, mins=5)

L(5, "O meu dia de trabalho", "Revisão: o presente em frases do dia a dia.",
  ["Descrever atividades no presente"],
  ex=[("Ik werk, ik lees, ik reis.","Trabalho, leio, viajo.")],
  review=["v-werken","v-lezen","v-kopen","v-doen","v-gaan","v-drinken","v-slapen","v-komen"],
  exs=[
    CJ("werken","jullie","___ jullie morgen?", ["Werken"], "jullie + infinitivo.", ["v-werken"]),
    CJ("lezen","u","___ u de krant?", ["Leest"], "Com u o -t mantém-se: leest u.", ["v-lezen"]),
    CJ("kopen","wij","Wij ___ eieren.", ["kopen"], "Plural.", ["v-kopen"]),
    MC("Qual está correta?", ["*Hij reist naar Duitsland.","Hij reizt naar Duitsland.|z → s: reist.","Hij reis naar Duitsland.|Com hij acrescenta-se -t."], "reizen → hij reist.", ["v-reizen"]),
    TR("pt-nl","Compro pão e leite.", ["Ik koop brood en melk"], "kopen → ik koop.", ["v-kopen","v-brood","v-melk"]),
    TR("nl-pt","Wat doen jullie vandaag?", ["O que fazem (vocês )hoje","O que vão fazer hoje"], "doen no plural.", ["v-doen","v-vandaag"]),
    FE(["Wij","slaapt","acht","uur."], 1, "slapen", "Plural: wij slapen.", ["v-slapen"]),
    CO("text","O dia do Tom", "Tom werkt in een ziekenhuis in Utrecht. Hij gaat met de fiets naar zijn werk. 's Middags drinkt hij koffie met zijn collega's. 's Avonds leest hij een boek en hij slaapt om elf uur.",
       [("Onde trabalha o Tom?", ["*Num hospital","Numa escola","Num restaurante"]),("O que faz à noite?", ["*Lê um livro","Viaja","Trabalha"]),("A que horas dorme?", ["*Às onze","Às oito","Às dez"])],
       "'s middags = à tarde; 's avonds = à noite.", ["v-werken","v-lezen","v-slapen"]),
    LI("Hij gaat met de fiets naar zijn werk.", ["Hij gaat met de fiets naar zijn werk"], "Ele vai de bicicleta para o trabalho.", "Frase típica dos Países Baixos.", ["v-gaan","v-fiets"]),
    SW("Escreva 2–3 frases sobre o seu dia (trabalhar, ler, beber café…).", ["Ik werk in [Lissabon|Amsterdam](.) Ik drink koffie","Ik werk(.) Ik lees een boek"],
       ["Usa pelo menos dois verbos diferentes","Raiz correta com «ik» (werk, lees, drink)","-t com hij/zij, se os usar"], 5, "Modelo: «Ik werk in Lissabon. Ik drink veel koffie en ik lees de krant.»", ["v-werken"]),
  ], diff=2, mins=6)

W()
